<?php define('ADMIN_CONTEXT',true);require '../includes/functions.php';$pageTitle='Admin sign in';$errors=[];if(post()){verify_csrf();$username=textval('username');$key=auth_key($username,'admin');if(auth_blocked($key))$errors[]='Too many attempts. Try again in 15 minutes.';else{$a=query('SELECT * FROM admins WHERE username=?',[$username])->fetch();if($a&&password_verify(textval('password'),$a['password'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id'];$_SESSION['csrf']=bin2hex(random_bytes(32));query('DELETE FROM login_attempts WHERE attempt_key=?',[$key]);redirect($a['must_change_password']?'admin/password.php':'admin/index.php');}fail_login($key);$errors[]='Invalid admin credentials.';}}require '../includes/header.php';?><section class="container section"><div class="panel auth-panel"><span class="eyebrow">STORE MANAGEMENT</span><h1>Admin sign in</h1><p class="muted">Authorized staff access.</p><?php errors($errors);?><form method="post" data-validate><?php csrf();?><label>Admin username<input name="username" maxlength="40" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" maxlength="72" required></label><button class="full">Sign in securely</button></form><p><a href="<?=e(url('index.php'))?>">Return to store</a></p></div></section><?php require '../includes/footer.php';?>
